-- VMC Xtreme foundation schema
create schema if not exists private;
create table public.vmc_roles(id smallint generated by default as identity primary key,name text not null unique check(name in('member','staff','manager','owner')),created_at timestamptz not null default now());
create table public.vmc_profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null check(length(trim(full_name)) between 2 and 120),username text unique,phone text,email text,avatar_url text,date_of_birth date,gender text,emergency_contact text,account_status text not null default 'active' check(account_status in('active','suspended','deactivated')),must_change_password boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint vmc_username_format check(username is null or username ~ '^@[A-Za-z0-9][A-Za-z0-9._-]{2,31}$'));
create table public.vmc_user_roles(user_id uuid primary key references public.vmc_profiles(id) on delete cascade,role_id smallint not null references public.vmc_roles(id),created_at timestamptz not null default now());
create table public.vmc_membership_plans(id bigint generated by default as identity primary key,name text not null,duration_unit text not null check(duration_unit in('day','week','month')),duration_count integer not null default 1 check(duration_count between 1 and 3650),session_type text not null check(session_type in('single','double')),price integer not null check(price>=0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(duration_unit,duration_count,session_type));
create table public.vmc_memberships(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.vmc_profiles(id) on delete cascade,plan_id bigint not null references public.vmc_membership_plans(id),start_date date,end_date date,status text not null default 'pending' check(status in('pending','active','expired','suspended','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.vmc_payments(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.vmc_profiles(id) on delete cascade,membership_id uuid not null references public.vmc_memberships(id) on delete cascade,amount integer not null check(amount>0),payment_method text not null check(payment_method in('Airtel Money','TNM Mpamba','National Bank','Cash')),receipt_reference text,payment_date timestamptz not null default now(),status text not null default 'pending' check(status in('pending','verified','rejected')),verified_by uuid references public.vmc_profiles(id),verified_at timestamptz,notes text,created_at timestamptz not null default now());
create table public.vmc_attendance(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.vmc_profiles(id) on delete cascade,checked_in_at timestamptz not null default now(),checked_out_at timestamptz,recorded_by uuid references public.vmc_profiles(id),created_at timestamptz not null default now());
create table public.vmc_member_photos(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.vmc_profiles(id) on delete cascade,storage_path text not null unique,is_profile_photo boolean not null default false,created_at timestamptz not null default now());
create table public.vmc_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.vmc_profiles(id),action text not null,entity_type text not null,entity_id uuid,metadata jsonb,created_at timestamptz not null default now());
insert into public.vmc_roles(name) values('member'),('staff'),('manager'),('owner') on conflict(name) do nothing;
insert into public.vmc_membership_plans(name,duration_unit,duration_count,session_type,price) values('Per Day','day',1,'single',2000),('Per Day','day',1,'double',3000),('Per Week','week',1,'single',8000),('Per Week','week',1,'double',10000),('Per Month','month',1,'single',30000),('Per Month','month',1,'double',35000) on conflict(duration_unit,duration_count,session_type) do update set name=excluded.name,price=excluded.price,is_active=true,updated_at=now();
create index vmc_memberships_member_id_idx on public.vmc_memberships(member_id); create index vmc_memberships_plan_id_idx on public.vmc_memberships(plan_id); create index vmc_payments_member_id_idx on public.vmc_payments(member_id); create index vmc_payments_membership_id_idx on public.vmc_payments(membership_id); create index vmc_payments_status_idx on public.vmc_payments(status); create index vmc_attendance_member_id_idx on public.vmc_attendance(member_id); create index vmc_member_photos_member_id_idx on public.vmc_member_photos(member_id); create index vmc_user_roles_role_id_idx on public.vmc_user_roles(role_id);
create or replace function private.vmc_has_role(required_role text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.vmc_user_roles ur join public.vmc_roles r on r.id=ur.role_id where ur.user_id=(select auth.uid()) and r.name=required_role);$$;
create or replace function private.vmc_is_staff() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.vmc_user_roles ur join public.vmc_roles r on r.id=ur.role_id where ur.user_id=(select auth.uid()) and r.name in('staff','manager','owner'));$$;
create or replace function private.vmc_is_manager_or_owner() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.vmc_user_roles ur join public.vmc_roles r on r.id=ur.role_id where ur.user_id=(select auth.uid()) and r.name in('manager','owner'));$$;
create or replace function private.vmc_is_owner() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.vmc_user_roles ur join public.vmc_roles r on r.id=ur.role_id where ur.user_id=(select auth.uid()) and r.name='owner');$$;
revoke execute on function private.vmc_has_role(text),private.vmc_is_staff(),private.vmc_is_manager_or_owner(),private.vmc_is_owner() from public; grant usage on schema private to authenticated; grant execute on function private.vmc_has_role(text),private.vmc_is_staff(),private.vmc_is_manager_or_owner(),private.vmc_is_owner() to authenticated;
alter table public.vmc_roles enable row level security; alter table public.vmc_profiles enable row level security; alter table public.vmc_user_roles enable row level security; alter table public.vmc_membership_plans enable row level security; alter table public.vmc_memberships enable row level security; alter table public.vmc_payments enable row level security; alter table public.vmc_attendance enable row level security; alter table public.vmc_member_photos enable row level security; alter table public.vmc_audit_logs enable row level security;
revoke all on table public.vmc_roles,public.vmc_profiles,public.vmc_user_roles,public.vmc_membership_plans,public.vmc_memberships,public.vmc_payments,public.vmc_attendance,public.vmc_member_photos,public.vmc_audit_logs from anon,authenticated;
grant select on public.vmc_roles to authenticated; grant select,update on public.vmc_profiles to authenticated; grant select on public.vmc_user_roles to authenticated; grant select on public.vmc_membership_plans to anon,authenticated; grant select,insert on public.vmc_memberships to authenticated; grant select,insert on public.vmc_payments to authenticated; grant select,insert,update on public.vmc_attendance to authenticated; grant select,insert,update,delete on public.vmc_member_photos to authenticated; grant select on public.vmc_audit_logs to authenticated;
create policy vmc_profiles_select_self_or_staff on public.vmc_profiles for select to authenticated using((select auth.uid())=id or(select private.vmc_is_staff()));
create policy vmc_profiles_update_self on public.vmc_profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy vmc_user_roles_self_or_staff on public.vmc_user_roles for select to authenticated using((select auth.uid())=user_id or(select private.vmc_is_staff()));
create policy vmc_plans_public_read on public.vmc_membership_plans for select to anon,authenticated using(is_active=true);
create policy vmc_memberships_self_read on public.vmc_memberships for select to authenticated using((select auth.uid())=member_id or(select private.vmc_is_staff()));
create policy vmc_memberships_self_insert on public.vmc_memberships for insert to authenticated with check((select auth.uid())=member_id);
create policy vmc_payments_self_read on public.vmc_payments for select to authenticated using((select auth.uid())=member_id or(select private.vmc_is_staff()));
create policy vmc_payments_self_insert on public.vmc_payments for insert to authenticated with check((select auth.uid())=member_id);
create policy vmc_attendance_self_or_staff_read on public.vmc_attendance for select to authenticated using((select auth.uid())=member_id or(select private.vmc_is_staff()));
create policy vmc_attendance_staff_insert on public.vmc_attendance for insert to authenticated with check((select private.vmc_is_staff()) and recorded_by=(select auth.uid()));
create policy vmc_attendance_staff_update on public.vmc_attendance for update to authenticated using((select private.vmc_is_staff())) with check((select private.vmc_is_staff()));
create policy vmc_photos_self_read on public.vmc_member_photos for select to authenticated using((select auth.uid())=member_id or(select private.vmc_is_staff()));
create policy vmc_photos_self_insert on public.vmc_member_photos for insert to authenticated with check((select auth.uid())=member_id);
create policy vmc_photos_self_update on public.vmc_member_photos for update to authenticated using((select auth.uid())=member_id) with check((select auth.uid())=member_id);
create policy vmc_photos_self_delete on public.vmc_member_photos for delete to authenticated using((select auth.uid())=member_id);
create policy vmc_audit_staff_read on public.vmc_audit_logs for select to authenticated using((select private.vmc_is_staff()));
create or replace function public.vmc_set_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now(); return new; end;$$;
create trigger vmc_profiles_updated_at before update on public.vmc_profiles for each row execute function public.vmc_set_updated_at();
create trigger vmc_membership_plans_updated_at before update on public.vmc_membership_plans for each row execute function public.vmc_set_updated_at();
create trigger vmc_memberships_updated_at before update on public.vmc_memberships for each row execute function public.vmc_set_updated_at();
create or replace function public.vmc_create_profile_for_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.vmc_profiles(id,full_name,email,phone,must_change_password) values(new.id,coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),coalesce(new.email,'VMC Member')),new.email,nullif(trim(new.raw_user_meta_data->>'phone'),''),coalesce((new.raw_user_meta_data->>'must_change_password')::boolean,true)) on conflict(id) do nothing; insert into public.vmc_user_roles(user_id,role_id) select new.id,r.id from public.vmc_roles r where r.name='member' on conflict(user_id) do nothing; return new; end;$$;
revoke all on function public.vmc_create_profile_for_new_user() from public;
create trigger vmc_on_auth_user_created after insert on auth.users for each row execute function public.vmc_create_profile_for_new_user();